<v-list-group v-if="$can('dashboard.view') || $can('users.view') || $can('roles.view')" prepend-icon="mdi-shield-account" no-action><template v-slot:activator><v-list-item-title v-if="!compactMode">User Management</v-list-item-title></template><v-list-item v-if="$can('dashboard.view')" to="/admin/branches" link><v-list-item-content v-if="!compactMode"><v-list-item-title>Branches</v-list-item-title></v-list-item-content></v-list-item><v-list-item v-if="$can('users.view')" to="/admin/users" link><v-list-item-content v-if="!compactMode"><v-list-item-title>Users</v-list-item-title></v-list-item-content></v-list-item><v-list-item v-if="$can('roles.view')" to="/admin/roles" link><v-list-item-content v-if="!compactMode"><v-list-item-title>Roles & Permissions</v-list-item-title></v-list-item-content></v-list-item></v-list-group>
<v-list-group v-if="$can('projects.view') || $can('properties.view')" prepend-icon="mdi-home-city" no-action><template v-slot:activator><v-list-item-title v-if="!compactMode">Real Estate</v-list-item-title></template><v-list-item v-if="$can('projects.view')" to="/admin/projects" link><v-list-item-content v-if="!compactMode"><v-list-item-title>Projects</v-list-item-title></v-list-item-content></v-list-item><v-list-item v-if="$can('projects.view')" to="/admin/blocks" link><v-list-item-content v-if="!compactMode"><v-list-item-title>Blocks</v-list-item-title></v-list-item-content></v-list-item><v-list-item v-if="$can('properties.view')" to="/admin/properties" link><v-list-item-content v-if="!compactMode"><v-list-item-title>Properties</v-list-item-title></v-list-item-content></v-list-item></v-list-group>
<v-list-group v-if="$can('customers.view') || $can('leads.view') || $can('site_visits.view')" prepend-icon="mdi-account-group" no-action><template v-slot:activator><v-list-item-title v-if="!compactMode">CRM</v-list-item-title></template><v-list-item v-if="$can('customers.view')" to="/admin/customers" link><v-list-item-content v-if="!compactMode"><v-list-item-title>Customers</v-list-item-title></v-list-item-content></v-list-item><v-list-item v-if="$can('leads.view')" to="/admin/leads" link><v-list-item-content v-if="!compactMode"><v-list-item-title>Leads</v-list-item-title></v-list-item-content></v-list-item><v-list-item v-if="$can('site_visits.view')" to="/admin/site-visits" link><v-list-item-content v-if="!compactMode"><v-list-item-title>Site Visits</v-list-item-title></v-list-item-content></v-list-item></v-list-group>
<v-list-group v-if="$can('sales.view') || $can('payments.view') || $can('installments.view') || $can('commissions.view') || $can('expenses.view') || $can('dashboard.view')" prepend-icon="mdi-cash-multiple" no-action><template v-slot:activator><v-list-item-title v-if="!compactMode">Sales & Finance</v-list-item-title></template><v-list-item v-if="$can('dashboard.view')" to="/admin/sales/dashboard" link><v-list-item-content v-if="!compactMode"><v-list-item-title>Sales Dashboard</v-list-item-title></v-list-item-content></v-list-item><v-list-item v-if="$can('sales.view')" to="/admin/bookings" link><v-list-item-content v-if="!compactMode"><v-list-item-title>Bookings</v-list-item-title></v-list-item-content></v-list-item><v-list-item v-if="$can('payments.view')" to="/admin/payments" link><v-list-item-content v-if="!compactMode"><v-list-item-title>Payments</v-list-item-title></v-list-item-content></v-list-item><v-list-item v-if="$can('installments.view')" to="/admin/installment-plans" link><v-list-item-content v-if="!compactMode"><v-list-item-title>Installment Plans</v-list-item-title></v-list-item-content></v-list-item><v-list-item v-if="$can('installments.view')" to="/admin/installments" link><v-list-item-content v-if="!compactMode"><v-list-item-title>Installments</v-list-item-title></v-list-item-content></v-list-item><v-list-item v-if="$can('commissions.view')" to="/admin/commissions" link><v-list-item-content v-if="!compactMode"><v-list-item-title>Commissions</v-list-item-title></v-list-item-content></v-list-item><v-list-item v-if="$can('expenses.view')" to="/admin/expenses" link><v-list-item-content v-if="!compactMode"><v-list-item-title>Expenses</v-list-item-title></v-list-item-content></v-list-item></v-list-group>
<v-list-group v-if="$can('accounting.view')" prepend-icon="mdi-calculator-variant-outline" no-action><template v-slot:activator><v-list-item-title v-if="!compactMode">Accounting</v-list-item-title></template><v-list-item to="/admin/accounting/chart-of-accounts" link><v-list-item-content v-if="!compactMode"><v-list-item-title>Chart of Accounts</v-list-item-title></v-list-item-content></v-list-item><v-list-item to="/admin/accounting/general-ledger" link><v-list-item-content v-if="!compactMode"><v-list-item-title>General Ledger</v-list-item-title></v-list-item-content></v-list-item><v-list-item to="/admin/accounting/trial-balance" link><v-list-item-content v-if="!compactMode"><v-list-item-title>Trial Balance</v-list-item-title></v-list-item-content></v-list-item></v-list-group><v-list-item v-if="$can('construction.view')" to="/admin/construction" link><v-list-item-icon><v-icon>mdi-hard-hat</v-icon></v-list-item-icon><v-list-item-content v-if="!compactMode"><v-list-item-title>Construction</v-list-item-title></v-list-item-content></v-list-item><v-list-group v-if="$can('reports.view')" prepend-icon="mdi-file-chart-outline" no-action><template v-slot:activator><v-list-item-title v-if="!compactMode">Reports & Audit</v-list-item-title></template><v-list-item to="/admin/reports" link><v-list-item-content v-if="!compactMode"><v-list-item-title>Financial Reports</v-list-item-title></v-list-item-content></v-list-item><v-list-item to="/admin/reports/financial-audit" link><v-list-item-content v-if="!compactMode"><v-list-item-title>Financial Audit</v-list-item-title></v-list-item-content></v-list-item></v-list-group><v-divider class="my-3"/><v-list-item v-if="$can('settings.view')" to="/admin/settings" link><v-list-item-icon><v-icon>mdi-cog</v-icon></v-list-item-icon><v-list-item-content v-if="!compactMode"><v-list-item-title>Settings</v-list-item-title></v-list-item-content></v-list-item>
</v-list></v-navigation-drawer>
<v-app-bar app flat outlined><v-app-bar-nav-icon @click="drawer=!drawer"/><div class="ml-2"><div class="text-h6 font-weight-bold app-title">{{ pageTitle }}</div><div class="caption grey--text hidden-sm-and-down">{{ today }}</div></div><v-spacer/>
<v-menu v-if="canSeeNotifications" offset-y left max-width="440">
<template v-slot:activator="{on,attrs}"><v-btn icon v-bind="attrs" v-on="on" @click="loadNotifications(false)"><v-badge :content="notificationCount" :value="notificationCount" color="error" overlap><v-icon>mdi-bell-outline</v-icon></v-badge></v-btn></template>
<v-card width="420"><v-card-title class="subtitle-1">Notifications<v-spacer/><v-chip v-if="notificationCount" x-small outlined class="mr-2">{{notificationCount}} alerts</v-chip><v-btn icon small @click="loadNotifications(false)"><v-icon small>mdi-refresh</v-icon></v-btn></v-card-title><v-divider/><v-list v-if="notifications.length" three-line dense class="notification-list"><v-list-item v-for="(n,i) in notifications" :key="i" @click="openNotification(n)"><v-list-item-icon><v-avatar size="34" class="notification-icon"><v-icon small :color="n.color">{{n.icon}}</v-icon></v-avatar></v-list-item-icon><v-list-item-content><v-list-item-title class="font-weight-medium">{{n.title}}</v-list-item-title><v-list-item-subtitle>{{n.message}}</v-list-item-subtitle><v-list-item-subtitle class="caption">{{notificationDate(n.date)}}</v-list-item-subtitle></v-list-item-content><v-list-item-icon><v-icon small color="grey">mdi-chevron-right</v-icon></v-list-item-icon></v-list-item></v-list><div v-else class="pa-8 text-center grey--text"><v-icon size="42" color="grey lighten-1">mdi-bell-check-outline</v-icon><div class="mt-2">No alerts requiring attention.</div></div></v-card></v-menu>
<v-btn icon @click="toggleDarkMode"><v-icon>{{ darkMode?'mdi-weather-sunny':'mdi-weather-night' }}</v-icon></v-btn><v-menu offset-y><template v-slot:activator="{on,attrs}"><v-btn text v-bind="attrs" v-on="on"><v-avatar size="34" color="primary"><v-img v-if="user&&user.profile_photo" :src="'/storage/'+user.profile_photo"/><span v-else class="white--text">{{ initials }}</span></v-avatar><span class="ml-2 hidden-sm-and-down">{{ userName }}</span><v-icon right>mdi-chevron-down</v-icon></v-btn></template><v-list><v-list-item to="/admin/profile"><v-list-item-icon><v-icon>mdi-account-circle</v-icon></v-list-item-icon><v-list-item-content><v-list-item-title>My Profile</v-list-item-title></v-list-item-content></v-list-item><v-list-item to="/admin/profile"><v-list-item-icon><v-icon>mdi-lock-reset</v-icon></v-list-item-icon><v-list-item-content><v-list-item-title>Change Password</v-list-item-title></v-list-item-content></v-list-item><v-divider/><v-list-item @click="logout"><v-list-item-icon><v-icon>mdi-logout</v-icon></v-list-item-icon><v-list-item-content><v-list-item-title>Logout</v-list-item-title></v-list-item-content></v-list-item></v-list></v-menu></v-app-bar>
<v-main><v-container fluid class="app-content pa-4 pa-md-7"><v-fade-transition mode="out-in"><router-view/></v-fade-transition></v-container></v-main></div>
</template>
<script>
import api from '../services/api'
export default {name:'AdminLayout',data(){return{notifications:[],notificationCount:0,notificationsLoading:false,notificationTimer:null,drawer:true,darkMode:localStorage.getItem('zeerak_dark_mode')==='1',compactMode:localStorage.getItem('zeerak_compact_nav')==='1'}},computed:{canSeeNotifications(){return this.$can('dashboard.view')||this.$can('installments.view')||this.$can('leads.view')||this.$can('site_visits.view')||this.$can('commissions.view')},today(){return new Intl.DateTimeFormat('en-PK',{weekday:'short',day:'2-digit',month:'short',year:'numeric'}).format(new Date())},user(){return this.$store.getters['auth/user']},userName(){return this.user?this.user.name:'User'},companyName(){return this.$store.getters['settings/companyName']||'ZeeraK Real Estate & Builders'},companyLogo(){return this.$store.getters['settings/logoUrl']||'/images/zeerak-logo.jpeg'},companySubtitle(){return this.$store.getters['settings/legalName']||'Management Portal'},initials(){if(!this.user)return'U';return this.user.name.split(' ').map(n=>n.charAt(0)).join('').substring(0,2).toUpperCase()},pageTitle(){const titles={dashboard:'Dashboard','sales-dashboard':'Sales Dashboard',users:'Users',roles:'Roles & Permissions',projects:'Projects','project-create':'Create Project','project-edit':'Edit Project','project-details':'Project Details',blocks:'Project Blocks',branches:'Branches','installment-plans':'Installment Plans',properties:'Property Inventory','property-create':'Create Property','property-details':'Property Details','property-edit':'Edit Property',customers:'Customers',leads:'Leads','site-visits':'Site Visits',bookings:'Bookings',payments:'Payments',installments:'Installments',commissions:'Commissions',expenses:'Expenses',construction:'Construction',reports:'Reports','financial-audit':'Financial Audit','chart-of-accounts':'Chart of Accounts','general-ledger':'General Ledger','trial-balance':'Trial Balance',settings:'Settings',profile:'My Profile'};return titles[this.$route.name]||'Zeerak ERP'}},mounted(){this.applyDarkMode(this.darkMode);this.$root.$on('theme-changed',this.applyDarkMode);this.$root.$on('compact-mode-changed',this.applyCompactMode);if(this.canSeeNotifications){this.loadNotifications(true);this.startNotificationPolling();document.addEventListener('visibilitychange',this.handleVisibilityChange)}},beforeDestroy(){this.stopNotificationPolling();document.removeEventListener('visibilitychange',this.handleVisibilityChange);this.$root.$off('theme-changed',this.applyDarkMode);this.$root.$off('compact-mode-changed',this.applyCompactMode)},methods:{startNotificationPolling(){if(this.notificationTimer||!this.canSeeNotifications)return;this.notificationTimer=setInterval(()=>{if(!document.hidden)this.loadNotifications(true)},300000)},stopNotificationPolling(){if(this.notificationTimer){clearInterval(this.notificationTimer);this.notificationTimer=null}},handleVisibilityChange(){if(!document.hidden&&this.canSeeNotifications)this.loadNotifications(true)},async loadNotifications(silent){if(this.notificationsLoading)return;this.notificationsLoading=true;try{const r=await api.get('/notifications',{skipGlobalLoader:!!silent,skipGlobalError:!!silent,skipGlobalMessage:true});this.notifications=r.data.items||[];this.notificationCount=Number(r.data.count||0)}catch(e){}finally{this.notificationsLoading=false}},openNotification(n){if(!n.route)return;const resolved=this.$router.resolve(n.route).route;if(this.$route.fullPath!==resolved.fullPath)this.$router.push(n.route).catch(()=>{})},notificationDate(v){if(!v)return'';const d=new Date(v);if(Number.isNaN(d.getTime()))return v;return d.toLocaleString('en-PK',{dateStyle:'medium',timeStyle:v.indexOf(':')!==-1?'short':undefined})},applyDarkMode(value){this.darkMode=value===true||value==='1';localStorage.setItem('zeerak_dark_mode',this.darkMode?'1':'0');document.documentElement.setAttribute('data-theme',this.darkMode?'dark':'light')},applyCompactMode(value){this.compactMode=!!value;localStorage.setItem('zeerak_compact_nav',this.compactMode?'1':'0')},toggleDarkMode(){this.applyDarkMode(!this.darkMode);this.$root.$emit('theme-changed',this.darkMode)},async logout(){await this.$store.dispatch('auth/logout');this.$router.push({name:'login'})}}}
</script>
<style scoped>
.v-main{background:#f4f7f5}.theme--dark .v-main{background:#0f1713!important}.app-content{max-width:1800px;margin:0 auto}.app-title{line-height:1.15}.v-card{border-radius:14px!important}.v-navigation-drawer{border-right:1px solid rgba(0,0,0,.06)!important}.theme--dark .v-navigation-drawer{background:#101a15!important;border-right-color:rgba(226,238,231,.09)!important}.v-list-item--active{border-radius:10px}.v-app-bar{backdrop-filter:blur(12px)}.notification-list{max-height:520px;overflow-y:auto}.notification-icon{background:rgba(128,128,128,.08)}.sidebar-brand-text{min-width:0;max-width:185px}.sidebar-brand-text .font-weight-bold{font-size:13px;line-height:1.2;white-space:normal}.sidebar-brand-text small{display:block;margin-top:3px;color:#8a948f;line-height:1.25}.sidebar-logo{border:2px solid rgba(22,81,52,.14);overflow:hidden}.theme--dark .sidebar-logo{border-color:rgba(91,183,125,.28)!important}
</style>
